/**
 * Difficulty parity and ordering (phase 3.1).
 *
 * Phase 3 shipped a seven-key chart that was *harder* than the phase 2.x one. This suite is the
 * regression that pins the fixed behaviour down, exactly as the corrective brief asks:
 *
 *  1. **Hard reproduces the v0.2.1 chart byte-for-byte** for the same analysis and seed. The golden
 *     chart in `tests/fixtures/hard-v0.2.1.json` was generated by the *actual* v0.2.1 code (see
 *     `scripts/emit-baseline-fixture.mts`), so this is a comparison against the old implementation,
 *     not against a re-implementation of it.
 *  2. **Easy < Normal < Hard.** Each simplification step lowers density, chord count, hold count and
 *     minimum spacing, and neither Easy nor Normal may exceed the baseline's two-note chords.
 *  3. **Hard is not harder than the baseline in any of the metrics the brief lists**: note count,
 *     notes per second, chord count, hold count/duration, spacings and lane transitions.
 */

import { describe, expect, it } from 'vitest';
import { generateChartSet } from '../src/chart/DifficultySet';
import { CHART_DIFFICULTIES, difficultyProfile } from '../src/chart/Difficulty';
import type { ChartStats } from '../src/chart/ChartGenerator';
import type { ChartNote } from '../src/chart/ChartTypes';
import { FIXTURE_SEED, FIXTURE_SONG, fixtureAnalysis } from './helpers/analysis-fixture';
import baseline from './fixtures/hard-v0.2.1.json';

const analysis = fixtureAnalysis();
const set = generateChartSet(analysis, { ...FIXTURE_SONG, seed: FIXTURE_SEED });
const hard = set.charts.hard!;

/** Metrics the brief asks to compare between the two generators. */
interface Metrics {
  noteCount: number;
  notesPerSecond: number;
  chordEvents: number;
  chordNotes: number;
  holdCount: number;
  maxSimultaneous: number;
  minGapMs: number;
  minSameLaneGapMs: number;
  laneTransitions: number;
  laneCount: number;
  lanesUsed: number;
}

function metricsOf(notes: readonly ChartNote[]): Metrics {
  const sorted = [...notes].sort((a, b) => a.timeMs - b.timeMs || a.lane - b.lane);
  const byTime = new Map<number, number>();
  for (const note of sorted) byTime.set(note.timeMs, (byTime.get(note.timeMs) ?? 0) + 1);
  const chordEvents = [...byTime.values()].filter((count) => count > 1).length;
  const chordNotes = [...byTime.values()].reduce((sum, count) => sum + Math.max(0, count - 1), 0);

  // Minimum spacing between two *distinct* instants: notes sharing a time are a chord, not a gap of
  // zero (that is what `maxSimultaneous` measures).
  let minGapMs = Number.POSITIVE_INFINITY;
  for (let index = 1; index < sorted.length; index += 1) {
    const gap = sorted[index]!.timeMs - sorted[index - 1]!.timeMs;
    if (gap > 0) minGapMs = Math.min(minGapMs, gap);
  }
  const byLane = new Map<number, number[]>();
  for (const note of sorted) {
    const times = byLane.get(note.lane) ?? [];
    times.push(note.timeMs);
    byLane.set(note.lane, times);
  }
  let minSameLaneGapMs = Number.POSITIVE_INFINITY;
  for (const times of byLane.values()) {
    for (let index = 1; index < times.length; index += 1) {
      minSameLaneGapMs = Math.min(minSameLaneGapMs, times[index]! - times[index - 1]!);
    }
  }
  let laneTransitions = 0;
  for (let index = 1; index < sorted.length; index += 1) {
    if (sorted[index]!.timeMs !== sorted[index - 1]!.timeMs && sorted[index]!.lane !== sorted[index - 1]!.lane) {
      laneTransitions += 1;
    }
  }
  const lanes = new Set(sorted.map((note) => note.lane));
  const lastEndMs = sorted.reduce(
    (max, note) => Math.max(max, note.type === 'hold' ? note.timeMs + (note.durationMs ?? 0) : note.timeMs),
    0,
  );
  return {
    noteCount: sorted.length,
    notesPerSecond: lastEndMs > 0 ? (sorted.length / Math.max(1, baseline.stats.chartDurationMs)) * 1000 : 0,
    chordEvents,
    chordNotes,
    holdCount: sorted.filter((note) => note.type === 'hold').length,
    maxSimultaneous: Math.max(0, ...byTime.values()),
    minGapMs: Number.isFinite(minGapMs) ? minGapMs : 0,
    minSameLaneGapMs: Number.isFinite(minSameLaneGapMs) ? minSameLaneGapMs : 0,
    laneTransitions,
    laneCount: difficultyProfile('hard').laneCount,
    lanesUsed: lanes.size,
  };
}

const baselineNotes = baseline.notes as ChartNote[];
const baselineMetrics = metricsOf(baselineNotes);

describe('seven-key parity with the v0.2.1 baseline', () => {
  it('is the same chart, note for note', () => {
    // The strongest statement available: same timings, same lanes, same note types, in the same
    // order. If this ever fails, Hard has changed shape and every stored seven-key chart disagrees
    // with what the current build would generate.
    expect(hard.chart.notes).toEqual(baselineNotes);
    expect(hard.chart.bpm).toBe(baseline.bpm);
    expect(hard.chart.laneCount).toBe(7);
    expect(hard.chart.notes.length).toBe(baseline.stats.noteCount);
  });

  it('is not harder than the baseline in any measured metric', () => {
    const current = metricsOf(hard.chart.notes);
    // Reported in the same order as the brief lists them, so a failure says what got harder.
    for (const key of [
      'noteCount',
      'chordEvents',
      'chordNotes',
      'holdCount',
      'maxSimultaneous',
      'laneTransitions',
    ] as const) {
      expect(current[key], `${key} must not increase`).toBeLessThanOrEqual(baselineMetrics[key]);
    }
    // Spacings may only get *wider* (a smaller minimum gap means a harder chart).
    expect(current.minGapMs).toBeGreaterThanOrEqual(baselineMetrics.minGapMs);
    expect(current.minSameLaneGapMs).toBeGreaterThanOrEqual(baselineMetrics.minSameLaneGapMs);
    expect(current.notesPerSecond).toBeLessThanOrEqual(baselineMetrics.notesPerSecond + 1e-9);
    expect(current.lanesUsed).toBe(baselineMetrics.lanesUsed);
    // The baseline never placed more than two notes on one instant, and neither may Hard now.
    expect(current.maxSimultaneous).toBe(baselineMetrics.maxSimultaneous);
    expect(current.maxSimultaneous).toBeLessThanOrEqual(difficultyProfile('hard').generation.maxChordSize);
  });

  it('keeps the SPACE lane meaning the primary beat', () => {
    const stats: ChartStats = hard.stats;
    expect(stats.spaceCount).toBeGreaterThan(0);
    expect(stats.spaceRatio).toBeLessThanOrEqual(difficultyProfile('hard').generation.maxSpaceRatio + 0.02);
    expect(stats.lanesUsed).toBe(7);
  });
});

describe('complexity ordering: Easy < Normal < Hard (baseline)', () => {
  const metrics = Object.fromEntries(
    CHART_DIFFICULTIES.map((difficulty) => [difficulty, metricsOf(set.charts[difficulty]!.chart.notes)]),
  ) as Record<(typeof CHART_DIFFICULTIES)[number], Metrics>;
  const stats = Object.fromEntries(
    CHART_DIFFICULTIES.map((difficulty) => [difficulty, set.charts[difficulty]!.stats]),
  ) as Record<(typeof CHART_DIFFICULTIES)[number], ChartStats>;

  it('rises in exactly this order', () => {
    expect(metrics.easy.notesPerSecond).toBeLessThan(metrics.normal.notesPerSecond);
    expect(metrics.normal.notesPerSecond).toBeLessThan(metrics.hard.notesPerSecond);
    expect(metrics.easy.noteCount).toBeLessThan(metrics.normal.noteCount);
    expect(metrics.normal.noteCount).toBeLessThan(metrics.hard.noteCount);
  });

  it('never asks for a bigger chord than the original two-note accent', () => {
    for (const difficulty of CHART_DIFFICULTIES) {
      expect(
        metrics[difficulty].maxSimultaneous,
        `${difficulty} must not exceed the baseline chord size`,
      ).toBeLessThanOrEqual(baselineMetrics.maxSimultaneous);
      expect(metrics[difficulty].maxSimultaneous).toBeLessThanOrEqual(
        difficultyProfile(difficulty).generation.maxChordSize,
      );
    }
  });

  it('simplifies chords, holds and spacing on the way down', () => {
    expect(metrics.normal.chordNotes).toBeLessThanOrEqual(metrics.hard.chordNotes);
    expect(metrics.easy.chordNotes).toBeLessThanOrEqual(metrics.normal.chordNotes);
    // Holds are *not* asserted to be monotonic in count: a hold is only placed where the analysis
    // implies a sustain, so a sparser chart can catch a sustain that a denser one's note placement
    // happens not to reach (this fixture: Easy 0, Normal 1, Hard 0). What must hold is the budget,
    // which is what actually bounds hold complexity for a player.
    const holdBudgets = CHART_DIFFICULTIES.map((difficulty) => difficultyProfile(difficulty).generation.maxHoldRatio);
    expect(holdBudgets[0]).toBeLessThan(holdBudgets[1]);
    expect(holdBudgets[1]).toBeLessThan(holdBudgets[2]);
    for (const difficulty of CHART_DIFFICULTIES) {
      expect(stats[difficulty].holdRatio).toBeLessThanOrEqual(
        difficultyProfile(difficulty).generation.maxHoldRatio + 0.02,
      );
      for (const note of set.charts[difficulty]!.chart.notes) {
        if (note.type === 'hold') expect(note.durationMs!).toBeGreaterThan(0);
      }
    }
    // A beginner chart keeps notes further apart than the baseline, in time and within one lane.
    expect(metrics.easy.minGapMs).toBeGreaterThan(metrics.hard.minGapMs);
    expect(metrics.easy.minSameLaneGapMs).toBeGreaterThanOrEqual(metrics.hard.minSameLaneGapMs);
    expect(difficultyProfile('easy').generation.minNoteGapMs).toBeGreaterThan(
      difficultyProfile('hard').generation.minNoteGapMs,
    );
    expect(difficultyProfile('normal').generation.minNoteGapMs).toBeGreaterThan(
      difficultyProfile('hard').generation.minNoteGapMs,
    );
  });

  it('shares the same musical events, at the same instants', () => {
    // Every difficulty is a *selection* from one analysis, so a note can only exist where an event
    // does — and a shared instant must stay in the same place in time (the charts differ in which
    // notes they keep, never in when the music happens).
    const beatMs = analysis.beatMs;
    for (const difficulty of CHART_DIFFICULTIES) {
      for (const note of set.charts[difficulty]!.chart.notes) {
        const onOnset = analysis.onsets.some((onset) => Math.abs(onset.timeMs - note.timeMs) <= 60);
        const onGrid = Math.abs(note.timeMs - Math.round(note.timeMs / beatMs) * beatMs) <= 25;
        expect(onOnset || onGrid, `${difficulty} note at ${note.timeMs}ms is off the music`).toBe(true);
      }
      expect(stats[difficulty].onsetAlignRatio).toBeGreaterThan(0.5);
    }
  });
});
